    shadow_res = CASE WHEN shadow_res > 0 THEN GREATEST(CEIL(shadow_res * 1.2), shadow_res + 1) ELSE shadow_res END,
    arcane_res = CASE WHEN arcane_res > 0 THEN GREATEST(CEIL(arcane_res * 1.2), arcane_res + 1) ELSE arcane_res END,
    dmg_min1 = CASE WHEN dmg_min1 > 0 THEN GREATEST(CEIL(dmg_min1 * 1.2), dmg_min1 + 1) ELSE dmg_min1 END,
    dmg_max1 = CASE WHEN dmg_max1 > 0 THEN GREATEST(CEIL(dmg_max1 * 1.2), dmg_max1 + 1) ELSE dmg_max1 END,
    dmg_min2 = CASE WHEN dmg_min2 > 0 THEN GREATEST(CEIL(dmg_min2 * 1.2), dmg_min2 + 1) ELSE dmg_min2 END,
    dmg_max2 = CASE WHEN dmg_max2 > 0 THEN GREATEST(CEIL(dmg_max2 * 1.2), dmg_max2 + 1) ELSE dmg_max2 END
WHERE entry = 300272;

